impl From<u16> for Objc {
    #[inline]
    fn from(x: u16) -> Self {
        num_traits::FromPrimitive::from_u16(x).unwrap_or(Self::Error)
    }
}

// Objc == u16
impl PartialEq<u16> for Objc {
    #[inline]
    fn eq(&self, x: &u16) -> bool {
        *self == Into::<Self>::into(*x)
    }
}

// u16 == Objc
impl PartialEq<Objc> for u16 {
    #[inline]
    fn eq(&self, x: &Objc) -> bool {
        *x == *self
    }
}
